cat > clamp.cjs <<'EOF'
exports.clamp = (value, min, max) => Math.min(Math.max(value, min), max);
EOF
cat > clamp.test.cjs <<'EOF'
const {test} = require('node:test');
const assert = require('node:assert/strict');
const {clamp} = require('./clamp.cjs');
test('returns min below the range', () => {
  assert.equal(clamp(-5, 0, 10), 0);
});
test('returns max above the range', () => {
  assert.equal(clamp(15, 0, 10), 10);
});
test('returns the value inside the range', () => {
  assert.equal(clamp(7, 0, 10), 7);
});
test('returns the bounds when value equals them', () => {
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});
EOF
npm test 2>&1 | tail -15

